import json
# ---- SVG: двухшереножный строй, вид сверху (СУ пп. 6–15.1) ----
W,H=400,300
c1=[70,120,170,220,270,320]; y1=110; y2=160
c2=[70,120,220,270,320]   # за 170 нет военнослужащего второй шеренги — неполный ряд
s=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}">',
   f'<rect x="0" y="0" width="{W}" height="{H}" fill="#f4f1e8"/>',
   '<path d="M200 70 L200 30" stroke="#333" stroke-width="3"/><path d="M190 42 L200 26 L210 42 Z" fill="#333"/>']
for x in c1: s.append(f'<circle cx="{x}" cy="{y1}" r="14" fill="#4a6b3a" stroke="#222" stroke-width="2"/><path d="M{x-6} {y1-8} L{x} {y1-16} L{x+6} {y1-8}" stroke="#fff" stroke-width="2" fill="none"/>')
for x in c2: s.append(f'<circle cx="{x}" cy="{y2}" r="14" fill="#4a6b3a" stroke="#222" stroke-width="2"/><path d="M{x-6} {y2-8} L{x} {y2-16} L{x+6} {y2-8}" stroke="#fff" stroke-width="2" fill="none"/>')
s.append(f'<circle cx="170" cy="{y2}" r="14" fill="none" stroke="#999" stroke-width="2" stroke-dasharray="4 3"/>')
s.append('</svg>')
SVG=''.join(s)
ALT='Двухшереножный строй, вид сверху. Кружки — военнослужащие, уголок на кружке и стрелка вверху показывают, куда военнослужащие обращены лицом. Пунктир — пустое место.'
ZONES=[
 {"x":12,"y":28,"w":10,"h":33,"label":"Левый фланг (левая оконечность строя)"},
 {"x":75,"y":28,"w":10,"h":33,"label":"Правый фланг (правая оконечность строя)"},
 {"x":58.5,"y":32,"w":5.5,"h":9,"label":"Промежуток по фронту между соседними военнослужащими одной шеренги (интервал)"},
 {"x":27,"y":41,"w":6,"h":8,"label":"Промежуток в глубину между первой и второй шеренгой (дистанция)"},
 {"x":38,"y":28,"w":9,"h":33,"label":"Ряд, где за военнослужащим первой шеренги никто не стоит (неполный ряд)"},
 {"x":12,"y":5,"w":73,"h":19,"label":"Сторона строя, в которую военнослужащие обращены лицом (фронт)"},
]
MAT='Схема: двухшереножный строй, вид сверху. Стрелка и уголки на кружках показывают, куда военнослужащие обращены лицом. Номера на схеме — области, которые можно выбрать.'
def hz(correct):
  return [dict(z, correct=(i in correct)) for i,z in enumerate(ZONES)]
media=[{"svg":SVG,"alt":ALT}]
items=[]
def add(**k): items.append(k)
